import{_ as e,o,c as t,a0 as r}from"./chunks/framework.IrjkP_YN.js";const u=JSON.parse('{"title":"商标法明年要改版，所以我把法条存进了数据库","description":"","frontmatter":{},"headers":[],"relativePath":"posts/law-as-data.md","filePath":"posts/law-as-data.md","lastUpdated":null}'),s={name:"posts/law-as-data.md"};function n(l,a,p,i,d,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="商标法明年要改版-所以我把法条存进了数据库" tabindex="-1">商标法明年要改版，所以我把法条存进了数据库 <a class="header-anchor" href="#商标法明年要改版-所以我把法条存进了数据库" aria-label="Permalink to &quot;商标法明年要改版，所以我把法条存进了数据库&quot;">​</a></h1><p>2026-09 · 项目：AI 取名助手</p><h2 id="事情是怎么开始的" tabindex="-1">事情是怎么开始的 <a class="header-anchor" href="#事情是怎么开始的" aria-label="Permalink to &quot;事情是怎么开始的&quot;">​</a></h2><p>我原来那个项目是给人取名的：表单填一下姓氏性别字数，后端去 Milvus 里检索诗词，出五个名字带出处。跑通了，也上线了。</p><p>九月中旬我想加个「品牌／产品取名」的方向，顺便做一层商标风险提示。最省事的做法很明显——把《商标法》第十条、第十一条抄进代码，写一堆 if。</p><p>抄到一半我顺手搜了下原文，然后愣住了。</p><p>商标法 <strong>2026 年 6 月 26 日</strong>刚修订通过，<strong>2027 年 1 月 1 日</strong>施行。禁止性标志那一条，从第十条整个搬到了第十五条。</p><p>也就是说，我代码里要是写死「第十条第一款第（一）项」，四个多月之后它就是一个<strong>已经不存在的编号</strong>。而我这个项目是想长期挂在那儿的，不是交个作业就删。</p><h2 id="所以法条一个字都不能写在代码里" tabindex="-1">所以法条一个字都不能写在代码里 <a class="header-anchor" href="#所以法条一个字都不能写在代码里" aria-label="Permalink to &quot;所以法条一个字都不能写在代码里&quot;">​</a></h2><p>最后建了两张表：</p><ul><li><code>law_version</code>：哪部法、哪个版本、什么时候生效、什么时候失效</li><li><code>law_clause</code>：条款号、条款原文、风险等级，外键指向版本</li></ul><p>现在代码里没有任何一句法条。要用的时候按<strong>今天的日期</strong>查「当前生效的那一版」，再把这一版底下的条款全捞出来，拼成提示词给模型。库里实测是 1 行版本 + 15 行条款。</p><p>生效日期我放在<strong>版本</strong>表上，不是条款表上。这个我一开始想错了，我当时的理由是「放哪都行，反正以后能扩展」。后来才反应过来：生效日期是「版本」的属性，不是「条款」的属性——放条款表上的话，同一个日期要重复十五遍。</p><h2 id="一个坑-条款号不能单独唯一" tabindex="-1">一个坑：条款号不能单独唯一 <a class="header-anchor" href="#一个坑-条款号不能单独唯一" aria-label="Permalink to &quot;一个坑：条款号不能单独唯一&quot;">​</a></h2><p>我本来给 <code>clause_number</code> 加了个唯一约束，觉得一个条款号当然只对应一条。</p><p>然后我想到新旧法会<strong>撞号</strong>：2019 版的第十五条讲的是「代理人抢注被代理人的商标」，2026 版的第十五条讲的是「禁止性标志」。完全不同的两件事，同一个编号。</p><p>只按条款号查，将来会<strong>静默取错</strong>——不报错，就是把另一个版本的内容给你。所以唯一约束改成了 <code>(version_id, clause_number)</code>。</p><p>这个坑我是先写了约束、后来才想到的，属于运气好。要是等到 2027 年才发现，那就是线上事故了。</p><h2 id="_2027-年-1-月-1-日那天我要干什么" tabindex="-1">2027 年 1 月 1 日那天我要干什么 <a class="header-anchor" href="#_2027-年-1-月-1-日那天我要干什么" aria-label="Permalink to &quot;2027 年 1 月 1 日那天我要干什么&quot;">​</a></h2><p>想清楚这个是我觉得最爽的一部分。</p><p>那天我要做的只有三件事：<code>law_version</code> 加一行（2026 修订版，生效日期 2027-01-01，同时把 2019 版的失效日期填上）、<code>law_clause</code> 加一批新条款、禁用字样的映射表加一个新版本的块。</p><p><strong>现有数据一个字都不用动。</strong></p><p>因为代码是按「今天的日期」查生效版本的，那天一到它自动就换成新版了。模型甚至不知道法条改了——它看到的永远是「一堆条款，每条前面带个编号」，编号是数据库主键，不是条款号字符串。</p><p>顺便说下失效日期那个查询，我写的是 <code>expiry_date &gt; 今天</code>，不是 <code>&gt;=</code>。因为「失效日期」的意思是「<strong>从这天起</strong>不再有效」，所以 2027-01-01 当天，2019 版就不该再被选中了。这样配下来任何一天都恰好命中一版，不重叠也不断档。我还加了个守卫：查出 0 行或者 2 行都直接报错，不默默取第一个。</p><h2 id="一个我到现在也不敢说一定对的地方" tabindex="-1">一个我到现在也不敢说一定对的地方 <a class="header-anchor" href="#一个我到现在也不敢说一定对的地方" aria-label="Permalink to &quot;一个我到现在也不敢说一定对的地方&quot;">​</a></h2><p>第十条第二款（就是地名那条）到底算「禁止使用」还是「不予注册」，我查了半天没查出个准话。</p><p>商标局的指引里写的是「不得作为商标注册和使用」，但好几篇实务文章把它放在「不予注册」的依据底下，理由是地名缺乏显著性、容易让人误认产地。有律所的文章干脆把两种观点都列出来了。</p><p>我最后填的是「禁止使用」。</p><p>我不是学法的，这一格我到现在也不敢说一定对。但我觉得<strong>知道这里有争议</strong>比填对了更重要——所以我的输出措辞在这一条上放得最软，写的是「存在被驳回风险」，不是「违反第十条」。</p><h2 id="数据是一个字一个字录进去的" tabindex="-1">数据是一个字一个字录进去的 <a class="header-anchor" href="#数据是一个字一个字录进去的" aria-label="Permalink to &quot;数据是一个字一个字录进去的&quot;">​</a></h2><p>15 条法条全部从国家知识产权局的官方页面抄的，<strong>没让模型生成过一条</strong>。</p><p>这个我是被吓过的。之前做人名版的时候我抓到过一次真幻觉：我的工具只返回了李白、陈子昂、李商隐三首，模型给我的出处却是岑参的「瀚海阑干百丈冰」和苏轼的「大江东去，浪淘尽」。</p><p><strong>最坑的是这两句都是真的诗。</strong> 用户去查，查得到，根本看不出来是编的。</p><p>法条要是让模型背，它会改字、会把两项合并成一项、会漏掉但书，而且写得特别流畅。那我后面那套「模型只给编号、代码拿着编号回表取原文」的机制，就等于在认认真真地保护一个假数据源。</p><h2 id="_15-条是怎么构成的" tabindex="-1">15 条是怎么构成的 <a class="header-anchor" href="#_15-条是怎么构成的" aria-label="Permalink to &quot;15 条是怎么构成的&quot;">​</a></h2><p>记一下，因为这里我也错过一次。</p><p>第十条第一款引导语 1 条 + 八个项 8 条 + 第十条第二款 1 条 + 第十一条第一款引导语 1 条 + 三个项 3 条 + 第十一条第二款 1 条 = 15。</p><p><strong>引导语必须单独占一行。</strong> 不然第（一）项的原文就成了「仅有本商品的通用名称、图形、型号的」这种半句话，模型看不到「下列标志不得作为商标注册」这个前提，它根本不知道这些项是在说什么。</p><p>我一开始算出来是 13 条，因为我漏了两条引导语。后来是对着数据库一行行数出来的。</p><h2 id="还没做的" tabindex="-1">还没做的 <a class="header-anchor" href="#还没做的" aria-label="Permalink to &quot;还没做的&quot;">​</a></h2><ul><li>2026 修订版的条款我一条都还没录，因为还没施行，而且我想等临近了再录，免得录错了没人发现</li><li>导入脚本重跑会撞唯一约束（版本已存在就进 else 分支，然后又插 15 条重复条款）。它是响亮失败不是静默失败，所以不危险，我打算 2027 年加新版本的时候一起修</li><li>第十条第一款第（四）项那个「官方标志、检验印记」，我名录里录了 10 条，其中 9 条是按定义推的，只有「中国强制性产品认证（CCC）」有权威依据（商标法释义里的唯一例子）。这 9 条我知道不实，措辞上也没敢写「违反第（四）项」，只写「存在被驳回风险」</li></ul><hr><p>代码在 <a href="https://github.com/wangxihong-dev/ai-name-assistant" target="_blank" rel="noreferrer">GitHub</a>，<code>backend/xh-ainame/models/law_version.py</code> 和 <code>law_clause.py</code> 就是这两张表。</p>',43)])])}const _=e(s,[["render",n]]);export{u as __pageData,_ as default};
